# =============================================================================
# FILE: backend/api/routes/auth_routes.py
# ROLE: Authentication endpoints
# -----------------------------------------------------------------------------
# POST /register        — create account, returns JWT token
# POST /login           — verify credentials, returns JWT token
# PUT  /user/goal       — update daily calorie goal (JWT required)
#
# All tokens are generated by api/auth.py (PyJWT, 24h expiry)
# Passwords are bcrypt-hashed in user_service.py
# =============================================================================
from flask import Blueprint, jsonify, request

from api.auth import create_token, token_required, get_current_user_id
from services import user_service

auth_bp = Blueprint("auth", __name__)


@auth_bp.route("/register", methods=["POST"])
def register():
    data = request.get_json() or {}
    name = data.get("name")
    email = data.get("email")
    password = data.get("password")
    daily_goal = data.get("daily_calorie_goal")

    if not name or not email or not password:
        return jsonify({"error": "name, email and password are required"}), 400

    user, error = user_service.register_user(name, email, password, daily_goal)
    if error:
        return jsonify({"error": error}), 409

    token = create_token(user["user_id"], user["name"])
    return jsonify({
        "message": "User registered successfully",
        "user_id": user["user_id"],
        "name": user["name"],
        "token": token,
        "daily_calorie_goal": user["daily_calorie_goal"],
    }), 201


@auth_bp.route("/login", methods=["POST"])
def login():
    data = request.get_json() or {}
    email = data.get("email")
    password = data.get("password")

    if not email or not password:
        return jsonify({"error": "email and password are required"}), 400

    user = user_service.login_user(email, password)
    if not user:
        return jsonify({"error": "Invalid email or password"}), 401

    token = create_token(user["user_id"], user["name"])
    return jsonify({
        "message": "Login successful",
        "user_id": user["user_id"],
        "name": user["name"],
        "token": token,
        "daily_calorie_goal": user["daily_calorie_goal"],
    }), 200


@auth_bp.route("/user/goal", methods=["PUT"])
@token_required
def update_goal():
    data = request.get_json() or {}
    goal = data.get("daily_calorie_goal")
    if goal is None:
        return jsonify({"error": "daily_calorie_goal is required"}), 400

    user_id = get_current_user_id()
    success = user_service.update_daily_goal(user_id, goal)
    if not success:
        return jsonify({"error": "User not found"}), 404

    return jsonify({
        "message": "Daily calorie goal updated successfully",
        "daily_calorie_goal": goal
    }), 200

